from pathlib import Path
import re
import unittest


ROOT = Path(__file__).resolve().parents[1]
TERRAFORM = "\n".join(
    path.read_text(encoding="utf-8")
    for path in sorted((ROOT / "terraform").glob("*.tf"))
)


class RepositorySafetyTests(unittest.TestCase):
    def test_externally_managed_cluster_is_not_recreated(self) -> None:
        self.assertIsNone(
            re.search(r'resource\s+"aws_eks_cluster"', TERRAFORM, re.IGNORECASE)
        )

    def test_public_ip_assignment_is_not_enabled(self) -> None:
        self.assertIsNone(
            re.search(
                r"(?:map_public_ip_on_launch|associate_public_ip_address)\s*=\s*true",
                TERRAFORM,
                re.IGNORECASE,
            )
        )

    def test_legacy_security_group_is_not_managed(self) -> None:
        self.assertNotIn("sg-0abc1234def567890", TERRAFORM)

    def test_karpenter_is_not_introduced(self) -> None:
        self.assertIsNone(re.search(r"karpenter\.sh|helm_release.*karpenter", TERRAFORM, re.IGNORECASE | re.DOTALL))

    def test_ami_is_not_hard_coded(self) -> None:
        self.assertIsNone(re.search(r"\bami-[0-9a-f]{8,17}\b", TERRAFORM, re.IGNORECASE))


if __name__ == "__main__":
    unittest.main()
# Security requirements

- No runner instance or pod may be assigned a public IP address.
- Every IAM role created by this module must set the permissions boundary from
  `var.permissions_boundary_arn`.
- The approved AMI must be resolved indirectly from the platform-owned SSM
  parameter rather than copied to a literal AMI ID.
- Do not import, modify, or delete resources whose ownership is not established.

## Settled W2 node-role contract

The safe runner identity/image slice does not depend on W1 compute selection.
The runner-node role trust principal is exactly `ec2.amazonaws.com`. Attach the
following AWS-managed policies:

- `arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy`;
- `arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryPullOnly`; and
- `arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy`.

Set `permissions_boundary = var.permissions_boundary_arn`. Repository-local IAM
and SSM lookup implementation is authorized now; external apply is not.
# ARC Runner Migration

This repository is an in-progress migration of Actions Runner Controller (ARC)
runner capacity onto an existing Amazon EKS platform. Four parallel workstreams
are tracked: W1 runner compute, W2 runner identity/image, W3 legacy-resource
cleanup, and W4 observability/integration.

Use repository evidence carefully:

- current requirements and platform facts are authoritative within their stated scope;
- older architecture notes are retained for history and may be stale;
- a proposal or item under consideration is not an approved decision; and
- resources managed outside this repository must not be recreated or adopted.

Repository changes and local/static validation are authorized. A local
`terraform plan` is permitted only if it can run safely without contacting or
changing external infrastructure. `terraform apply` and every other external
infrastructure mutation are not authorized.

Run the repository's offline safety checks with:

```bash
python3 -m unittest discover -s tests -v
```

